We also need to introduce the
following spaces.
\begin{eqnarray*}
\begin{split}
L^2(0,T;\mathbb{R})=&\Big\{x:[0,T]\to
\mathbb{R}\Bigm|x(\cdot)\ \text{\rm is deterministic such that}\int_0^T|x(s)|^2ds<\infty\Big\},\\

L_\mathcal{F}^2(0,T;\mathbb{R})=&\Big\{x:[0,T]\times\Omega\to \mathbb{R}\Bigm|
x(\cdot)\hbox{ is
$\mathcal{F}_t$-adapted process such that }

\mathbb{E}\int_0^T|x(s)|^2ds<\infty\Big\},\\

C(0,T;\mathbb{R})=&\Big\{x:[0,T]\to \mathbb{R}\Bigm| x(\cdot)\hbox{ is
deterministic and continuous on $[0,T]$} \Big\}.
\end{split}
\end{eqnarray*}

In particular, by taking expectation,

\begin{equation} \mathbb{E}\overline{x}_{i}(t)=\widehat{\varphi }(t)+\int_0^t\widehat{f}(t,s)a(s)ds+\frac{1}{R}
\int_{0}^{T}M(t,s)[\gamma a(s)+\eta-\mathbb{E}\overline{x}_{i}(s)]ds,
\end{equation}

where

\begin{eqnarray} M(t,s)=\int_{0}^{s\wedge t}\widehat{c}(t,r)\widehat{c}(s,r)dr,\quad
t,s\in[0,T].
\end{eqnarray}

Given $a(s)$, using Theorem \ref{theorem-1}, we can define $\Gamma a$
by
\begin{equation} \lbrack \Gamma a](t)=\widehat{\varphi
}(t)+\int_0^t\widehat{f}(t,s)a(s)ds
+\frac{1}{R}
\int_{0}^{T}M(t,s)\big\{\gamma a(s)+\eta-[\Gamma a](s)\big\}ds.
\end{equation}

More
precisely, by using Lemma 1.1. in \cite{Y 1996}, we can rewrite
(\ref{3.14}) as

\begin{equation} \widehat{a}(t)=\widetilde{\varphi}(t)+\frac{1}{R}\int_{0}^{T}\widetilde{M}(t,s)[(\gamma -1)\widehat{a}(s)+\eta ]ds,
\end{equation}

where

\begin{align} \widetilde{\varphi}(t)&=\widehat{\varphi}(t)+\int_{0}^{t}\widetilde{P}(t,s)\widehat{\varphi}
(s)ds, \nonumber \\
\widetilde{M}(t,s)&=M(t,s)+\int_{0}^{t}\widetilde{P}(t,r)M(r,s)dr,
\end{align}

and

\begin{eqnarray} \widetilde{P}(t,s) = \sum\limits_{k=1}^{\infty
}\widetilde{\Lambda}^{k}(t,s), \quad \widetilde{\Lambda}^{1}(t,s)
=\widehat{f}(t,s), \quad
\widetilde{\Lambda}^{k+1}(t,s)=\int_{s}^{t}\widehat{f}(t,r)\widetilde{\Lambda}^{k}(r,s)dr.
\end{eqnarray}

If we apply control $\widehat{u}_j$ in (\ref{3.18}) to all the player except $\mathcal{A}_i,$ that is, for $j\neq i$,

\begin{align}
x_{j}(t) = & \; \varphi(t)+\int_{0}^{t}b(t,s)x_{j}(s)ds+\int_{0}^{t}f(t,s)[x^{N}(s)-\widehat{a}(s)]ds \nonumber \\
& +\int_{0}^{t}f(t,s)\widehat{a}(s)ds+\int_{0}^{t}c(t,s)\widehat{u}_{j}(s)ds+\int_{0}^{t}\sigma (t,s)dW_{j}(s), \end{align}

while for player $i$,

\begin{align}
x_{i}(t) = & \; \varphi(t)+\int_{0}^{t}b(t,s)x_{i}(s)ds+\int_{0}^{t}c(t,s)u_{i}(s)ds \nonumber \\
&+\int_{0}^{t}\sigma (t,s)dW_{i}(s)+\int_{0}^{t}f(t,s)x^{N}(s)ds, \end{align}

then similar as Lemma \ref{lemma-3} above, we also have the
following result.

We define by

\begin{eqnarray} \widehat{u}_i(t)=-\frac{1}{R}c(t)\mathbb{E}^{\mathcal{F}_t}\!\!\int_t^Te^{\int_t^sb(r)dr}[x_i(s) -\gamma\widehat{a}(s)-\eta]ds,\quad 1\leq i\leq N,
\end{eqnarray}

where $\widehat{a}$ is the solution of NCE equation and

\begin{align}
x_{i}(t) = & \; x(0)e^{\int_{0}^{t}b(r)dr}+\int_{0}^{t}\sigma (s)e^{\int_{s}^{t}b(r)dr}dW_{i}(s) \nonumber \\
& -\frac{1}{R}\int_{0}^{t}|c(s)|^2\mathbb{E}^{\mathcal{F}_{s}}\int_{s}^{T}e^{\int_{s}^{r}b(v)dv+\int_s^tb(r)dr} [x_{i}(r)-\gamma\widehat{a}(r)-\eta]drds, \end{align}

then we get the following asymptotic equilibrium analysis in present setting.

By introducing function $\Phi_1 $ as

\begin{eqnarray} \left\{\begin{array}{rl} \displaystyle\frac{\partial \Phi_1(t,s)}{\partial t}
& = \displaystyle A(t)\Phi_1(t-h,s)+\int_{t-h}^{t}B(t,r)\Phi_1(r,s)dr,\ t\geq
0, \\ [5mm] \Phi_1(0,0) & = 1, \quad \Phi_1(t,s)=0, \quad t<0,
\end{array}\right.
\end{eqnarray}
we transform (\ref{4.5}) into (see \cite{L 1973}, \cite{O-Z
2010})
\begin{eqnarray} x_{i}(t)=\psi(t)+\int_{0}^{t}K(t,s)u_i(s)ds+\int_{0}^{t}\Phi_1
(t,s)D(s)dW_i(s),
\end{eqnarray}
where $K(t,s)=\Phi_1(t,s)C(s),$ and

\begin{eqnarray*}
\psi(t)=\Phi_1(t,0)k(0)+\int_{-h}^{0}\left[ \Phi_1
(t,s+h)A(s+h)+\int_{0}^{h}\Phi_1(t,u)B(u,s)du\right] k(s)ds .
\end{eqnarray*}

On the other hand, (\ref{4.7}) is one special case of Equation (\ref{2.1}) by letting $b=0,$ hence for $t,s\in[0,T]$,

\begin{eqnarray*}
& & P(t,s) = 0, \quad \widehat{c}(s,t)=\Phi_1(t,s)C(s), \\
& & \widehat{\varphi }(t) = \psi(t), \quad \widehat{\sigma}_{i}(t)=\int_{0}^{t}\Phi_1(t,s)D(s)dW_{i}(s),\\
& & M(t,s) = \int_{0}^{s\wedge t}\Phi_1(t,r)\Phi_1(s,r)|C(r)|^{2}dr.
\end{eqnarray*}

Therefore, (\ref{4.12}) is one special case of (\ref{2.1}) with $b=0,$ and

\begin{eqnarray*}
& & P(t,s) = 0,\quad \widehat{c}(s,t)=\Phi_2(s,t+h)C(t+h), \\
& & \widehat{\varphi }(t) = \Phi_2(t,0)k(0),\quad \widehat{\sigma }_i(t)=\int_{0}^{t}\Phi_2(t,s)D(s)dW_{i}(s),\\
& & M(t,s) = \int_{0}^{s\wedge t}\Phi_2(t,r+h)\Phi_2(s,r+h)|C(r+h)|^{2}dr.
\end{eqnarray*}

Given $\widehat{a}$ being the NCE solution, we define 

\begin{eqnarray} \widehat{u}_{i}(t)=-\frac{1}{R}C(t+h)\mathbb{E}^{\mathcal{F}_{t}}\3n\int_{t}^{T}\Phi_2
(s,t+h)[x_{i}(s)-\gamma \widehat{a}(s)-\eta]ds,\quad t\in[0,T],
\end{eqnarray}

while $x_{i}$ satisfies

\begin{align*}
x_{i}(t) = & \; \Phi_2(t,0)k(0)+\int_{0}^{t}\Phi_2(t,s)D(s)dW_{i}(s) \\
& -R^{-1}\int_{0}^{T}\int_{0}^{s\wedge t}\Phi_2(t,r+h)\Phi_2(s,r+h)|C(r+h)|^{2}\mathbb{E}^{\mathcal{F}_{r}}[x_{i}(s)-\gamma\widehat{a}(s)-\eta]drds,
\end{align*}

